class LocalDailyCheckIn extends DataClass
    implements Insertable<LocalDailyCheckIn> {
  final String id;
  final String profileId;
  final DateTime day;
  final double? sleepHours;
  final int? energyScore;

  /// Il movimento non strutturato della giornata. Serve ad accorgersene, non a
  /// misurarlo con precisione: il plateau classico arriva quando il NEAT crolla
  /// senza che nessuno se ne accorga.
  final int? steps;
  final int? walkMinutes;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  const LocalDailyCheckIn({
    required this.id,
    required this.profileId,
    required this.day,
    this.sleepHours,
    this.energyScore,
